<h2>Tambah Kategori</h2><form action="proses/proseskategori.php?aksi=tambah" method="post" enctype="multipart/form-data"><div class="form-group"><label>Nama Kategori</label><input class="form-control" name="namakategori" required></div><div class="form-group"><label>Gambar Kategori</label><input class="form-control-file" type="file" name="foto" accept="image/jpeg,image/png,image/webp" required><small class="text-muted">JPG, PNG, WEBP, maksimal 3 MB.</small></div><button class="btn btn-primary">Simpan</button></form>